570	func TestSessionMergeHTTPConcurrent(t *testing.T) {
571		h, _ := newTestHandler(t)
572		createSessionViaHTTP(t, h, "dev", "sess")
573	
574		const n = 40
575		var wg sync.WaitGroup
576		errs := make(chan error, n)
577		var applied int64
578		var mu sync.Mutex
579		for i := 0; i < n; i++ {
580			wg.Add(1)
581			go func(i int) {
582				defer wg.Done()
583				// Every goroutine merges from baseCursor 0 with a unique top-level
584				// key, so serialization leaves each merge applicable.
585				w, body := postSessionMerge(t, h, "sess", "doc", map[string]any{
586					"baseCursor": 0,
587					"change": map[string]any{
588						"id":      fmt.Sprintf("id-%02d", i),
589						"payload": map[string]any{fmt.Sprintf("k%02d", i): i},
590					},
591				})
592				if w.Code != http.StatusOK {
593					errs <- fmt.Errorf("merge %d status %d: %s", i, w.Code, w.Body.String())
594					return
595				}
596				mu.Lock()
597				if body["outcome"] == "applied" {
598					applied++
599				}
600				mu.Unlock()
601			}(i)
602		}
603		wg.Wait()
604		close(errs)
605		for err := range errs {
606			t.Error(err)
607		}
608	
609		// Exactly one request won the applied race; the whole set took effect with
610		// no cursor reused and no record lost.
611		if applied != 1 {
612			t.Fatalf("applied count = %d, want 1", applied)
613		}
614		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
615		if w.Code != http.StatusOK {
616			t.Fatal(w.Body.String())
617		}
618		rows := body["changes"].([]any)
619		if len(rows) != n || body["nextCursor"].(float64) != n {
620			t.Fatalf("stored %d changes, nextCursor = %v, want %d", len(rows), body["nextCursor"], n)
621		}
622		seen := make(map[float64]bool, n)
623		for _, row := range rows {
624			cursor := row.(map[string]any)["cursor"].(float64)
625			if seen[cursor] {
626				t.Fatalf("cursor %v allocated twice", cursor)
627			}
628			seen[cursor] = true
629		}
630	}
